<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {useCatalog} from '../stores/catalog'
import {discover} from '../services/discovery'
import type {Match} from '../types'
const store=useCatalog(),router=useRouter(),mode=ref<'endpoint'|'requirement'>('endpoint'),query=ref(''),results=ref<Match[]>([]),searched=ref(false),filterStatus=ref('all'),filterTeam=ref('all')
const teams=computed(()=>[...new Set(store.apis.map(a=>a.team))].sort())
const visible=computed(()=>results.value.filter(r=>(filterStatus.value==='all'||r.api.status===filterStatus.value)&&(filterTeam.value==='all'||r.api.team===filterTeam.value)))
function search(){store.metrics.searches++;results.value=discover(store.apis,query.value,mode.value==='requirement');searched.value=true}
function sample(q:string){query.value=q;search()}
function reuse(r:Match){store.recordReuse();router.push({path:'/docs',query:{id:r.api.id}})}
function extend(r:Match){router.push({path:'/create',query:{extend:r.api.id}})}
function exportResults(){const rows=[['API','Version','Score','Backend','Gateway','Owner','Status'],...visible.value.map(x=>[x.api.name,x.api.version,String(x.score),x.api.backend,x.api.suffix,x.api.team,x.api.status])];const csv=rows.map(r=>r.map(v=>'"'+v.replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='integraiq-discovery.csv';a.click();URL.revokeObjectURL(url)}
onMounted(()=>{const q=sessionStorage.getItem('integraiq-requirement');if(q){sessionStorage.removeItem('integraiq-requirement');query.value=q;mode.value='requirement';search()}})
</script>
<template><h1>API Discovery</h1><p class="sub">Find an existing API before creating another integration.</p><div class="seg"><button :class="{on:mode==='endpoint'}" @click="mode='endpoint';searched=false">Endpoint / keyword</button><button :class="{on:mode==='requirement'}" @click="mode='requirement';searched=false">Business requirement</button></div>
<div class="card searchbox"><label for="query">{{mode==='requirement'?'Describe your integration requirement':'API name, backend URL or gateway suffix'}}</label><textarea v-if="mode==='requirement'" id="query" v-model="query" rows="3" placeholder="Summarize documents and retrieve the result" @keydown.ctrl.enter="search"/><div v-else class="row"><input id="query" v-model="query" placeholder="https://ml.internal.contoso.com/inference" @keydown.enter="search"/><button class="btn" @click="search">Search</button></div><div class="actions" v-if="mode==='requirement'"><button class="btn" @click="search">✦ Analyze requirement</button></div><p class="ai-note">{{mode==='requirement'?'Explainable local keyword/concept matching — not a live AI model.':'Endpoint and catalog metadata are matched locally.'}}</p><div class="try">Try: <button class="lnk" @click="sample('Embeddings API')">Embeddings API</button> · <button class="lnk" @click="sample('https://ml.internal.contoso.com/inference')">Inference URL</button> · <button class="lnk" @click="sample('fraud scoring')">Fraud scoring</button></div></div>
<div v-if="searched"><div class="toolbar"><div class="res-h"><h2 style="margin:0">{{visible.length}} candidate APIs</h2><span class="pill">{{results[0]?.score??0}}% top match</span></div><button class="btn ghost sm" v-if="visible.length" @click="exportResults">Export CSV</button></div><div class="row" style="margin-bottom:14px"><div><label>Status</label><select v-model="filterStatus"><option value="all">All statuses</option><option>active</option><option>beta</option><option>deprecated</option></select></div><div><label>Team</label><select v-model="filterTeam"><option value="all">All teams</option><option v-for="t in teams" :key="t">{{t}}</option></select></div></div><div v-if="!visible.length" class="card empty">No matching APIs in this demo catalog. Review the search scope before proposing a new one.<div class="actions" style="justify-content:center"><button class="btn" @click="router.push('/create')">Create API draft</button></div></div><div v-for="r in visible" :key="r.api.id" class="card found"><div class="f-top"><span class="f-ic">⚡</span><div class="f-ti"><span class="tag" :class="'st-'+r.api.status">{{r.api.status}}</span><h2>{{r.api.name}} <span class="ver">{{r.api.version}}</span></h2><p>{{r.api.desc}}</p></div><div class="f-cnt"><b>{{r.score}}%</b><span>Match score</span></div></div><div class="f-meta"><div><i>Backend</i><code>{{r.api.backend}}</code></div><div><i>Gateway</i><code>{{r.api.suffix}}</code></div><div><i>Owning team</i>{{r.api.team}}</div></div><div class="f-rec" :class="r.score>=90?'':r.score>=60?'rv':'warn'"><b>{{r.score>=90?'Strong reuse match':r.score>=60?'Review for reuse':'Possible overlap'}}</b><p>{{r.why}}. Confirm coverage with the owning team before deciding.</p></div><div class="f-ops"><div v-for="op in r.api.ops.slice(0,4)" :key="op[0]+op[1]" class="f-op"><span class="m" :class="op[0]">{{op[0]}}</span><code>{{op[1]}}</code><span>{{op[2]}}</span></div></div><div class="f-act"><button class="btn" @click="reuse(r)">Reuse / view docs</button><button class="btn ghost" @click="extend(r)">Extend API</button></div></div></div>
</template>
